import{c as t,Q as r,j as e,m as i}from"./chunks/framework.BnKG8mJY.js";const m=JSON.parse('{"title":"User Guide","description":"","frontmatter":{"title":"User Guide","outline":"deep"},"headers":[],"relativePath":"guide/user-guide.md","filePath":"guide/user-guide.md"}'),n={name:"guide/user-guide.md"};function l(d,a,s,o,u,h){return r(),e("div",null,[...a[0]||(a[0]=[i('<h1 id="user-guide" tabindex="-1">User Guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User Guide&quot;">​</a></h1><p>Panduan penggunaan Transport Management System (TMS) untuk semua role pengguna.</p><h2 id="login" tabindex="-1">Login <a class="header-anchor" href="#login" aria-label="Permalink to &quot;Login&quot;">​</a></h2><ol><li>Buka aplikasi di browser</li><li>Masukkan username dan password</li><li>Klik <strong>Login</strong></li></ol><p>Setelah login, pengguna diarahkan ke halaman sesuai role:</p><ul><li><strong>Admin/User/Mekanik</strong> → Dashboard</li><li><strong>CS</strong> → Schedule Pengiriman</li></ul><h2 id="navigasi-menu" tabindex="-1">Navigasi Menu <a class="header-anchor" href="#navigasi-menu" aria-label="Permalink to &quot;Navigasi Menu&quot;">​</a></h2><h3 id="menu-utama-admin-user" tabindex="-1">Menu Utama (Admin/User) <a class="header-anchor" href="#menu-utama-admin-user" aria-label="Permalink to &quot;Menu Utama (Admin/User)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Menu</th><th>Sub-menu</th><th>Fungsi</th></tr></thead><tbody><tr><td>Dashboard</td><td>Home</td><td>Ringkasan performa</td></tr><tr><td></td><td>Schedule Pengiriman</td><td>Jadwal pengiriman</td></tr><tr><td></td><td>Monitoring Kendaraan</td><td>Status armada</td></tr><tr><td></td><td>Lokasi Truk</td><td>Peta GPS live</td></tr><tr><td></td><td>KM Bulanan Truk</td><td>Rekap mileage bulanan</td></tr><tr><td>Calendar</td><td>—</td><td>Kalender event</td></tr><tr><td>Master</td><td>Truck, Driver, Customer, Area, Warehouse, Subcont, Admin</td><td>Data master</td></tr><tr><td>Data Transport</td><td>Data Truck, Data Chasis, Data Supir</td><td>Data historis kendaraan &amp; supir</td></tr><tr><td>Transaksi</td><td>Sales Cost, Subcontractor, Repair</td><td>Transaksi operasional</td></tr></tbody></table><h3 id="menu-cs" tabindex="-1">Menu CS <a class="header-anchor" href="#menu-cs" aria-label="Permalink to &quot;Menu CS&quot;">​</a></h3><p>CS hanya bisa mengakses:</p><ul><li>Schedule Pengiriman</li><li>User Profile</li></ul><h3 id="menu-mekanik" tabindex="-1">Menu Mekanik <a class="header-anchor" href="#menu-mekanik" aria-label="Permalink to &quot;Menu Mekanik&quot;">​</a></h3><p>Mekanik bisa mengakses semua kecuali:</p><ul><li>Master Data (tidak tersedia)</li><li>Sales Cost &amp; Subcontractor (tidak tersedia)</li><li>Hanya bisa akses <strong>Repair</strong> di menu Transaksi</li></ul><h2 id="dashboard-home" tabindex="-1">Dashboard (Home) <a class="header-anchor" href="#dashboard-home" aria-label="Permalink to &quot;Dashboard (Home)&quot;">​</a></h2><p>Halaman utama setelah login menampilkan:</p><h3 id="ringkasan-dashboard" tabindex="-1">Ringkasan Dashboard <a class="header-anchor" href="#ringkasan-dashboard" aria-label="Permalink to &quot;Ringkasan Dashboard&quot;">​</a></h3><ul><li><strong>Sales Cost &amp; Subcontractor Metrics</strong> — jumlah transaksi per bulan dengan indikator naik/turun</li><li><strong>Detail Sales Cost (Monthly)</strong> — Sales, Total Cost, Gross Profit bulan terpilih</li><li><strong>Monthly Sales Transaction</strong> — grafik bar transaksi per bulan</li><li><strong>Truck Transaction Average</strong> — persentase penggunaan truck per bulan</li><li><strong>Calendar Event List</strong> — daftar event terbaru</li></ul><h3 id="expiry-alerts" tabindex="-1">Expiry Alerts <a class="header-anchor" href="#expiry-alerts" aria-label="Permalink to &quot;Expiry Alerts&quot;">​</a></h3><p>Peringatan dokumen kendaraan/supir yang mendekati atau sudah expired.</p><h3 id="statistics-sales-cost" tabindex="-1">Statistics Sales Cost <a class="header-anchor" href="#statistics-sales-cost" aria-label="Permalink to &quot;Statistics Sales Cost&quot;">​</a></h3><p>Grafik area chart (Sales, Total Cost, Gross Profit) dengan filter Monthly/Quarterly/Annually.</p><h3 id="statistics-subcontractor-cost" tabindex="-1">Statistics Subcontractor Cost <a class="header-anchor" href="#statistics-subcontractor-cost" aria-label="Permalink to &quot;Statistics Subcontractor Cost&quot;">​</a></h3><p>Grafik area chart sama seperti Sales Cost tapi untuk data Subcontractor.</p><h2 id="schedule-pengiriman" tabindex="-1">Schedule Pengiriman <a class="header-anchor" href="#schedule-pengiriman" aria-label="Permalink to &quot;Schedule Pengiriman&quot;">​</a></h2><p>Halaman untuk melihat jadwal pengiriman yang sedang berjalan.</p><h3 id="filter" tabindex="-1">Filter <a class="header-anchor" href="#filter" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><ul><li><strong>Tanggal Delivery Order</strong> — filter berdasarkan tanggal kirim</li><li><strong>Tanggal Arrival Order</strong> — filter berdasarkan tanggal tiba</li><li><strong>Kata Kunci</strong> — cari berdasarkan No Police, Customer, Driver, atau No DN</li></ul><h3 id="informasi-yang-ditampilkan" tabindex="-1">Informasi yang Ditampilkan <a class="header-anchor" href="#informasi-yang-ditampilkan" aria-label="Permalink to &quot;Informasi yang Ditampilkan&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kolom</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Delivery Order</td><td>Tanggal pengiriman</td></tr><tr><td>No. Police</td><td>Plat nomor kendaraan</td></tr><tr><td>Driver</td><td>Nama supir</td></tr><tr><td>Customer</td><td>Nama pelanggan</td></tr><tr><td>Rute</td><td>Area/rute pengiriman</td></tr><tr><td>Arrival Order</td><td>Tanggal tiba</td></tr><tr><td>No. PO</td><td>Nomor Purchase Order</td></tr><tr><td>Jenis Pengiriman</td><td>Tipe pengiriman</td></tr><tr><td>DN</td><td>Jumlah Delivery Note</td></tr><tr><td>Trip</td><td>Nomor trip</td></tr></tbody></table><h3 id="detail-dn" tabindex="-1">Detail DN <a class="header-anchor" href="#detail-dn" aria-label="Permalink to &quot;Detail DN&quot;">​</a></h3><p>Klik baris untuk expand dan melihat detail DN:</p><ul><li>No. DN, Pickup, Drop, Qty, PKG, G.W, No. Container, No. Aju, Remarks</li></ul><h2 id="monitoring-kendaraan" tabindex="-1">Monitoring Kendaraan <a class="header-anchor" href="#monitoring-kendaraan" aria-label="Permalink to &quot;Monitoring Kendaraan&quot;">​</a></h2><p>Halaman untuk memantau status seluruh armada berdasarkan aktivitas operasional.</p><h3 id="summary-cards" tabindex="-1">Summary Cards <a class="header-anchor" href="#summary-cards" aria-label="Permalink to &quot;Summary Cards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Total Kendaraan</td><td>Jumlah seluruh armada aktif</td></tr><tr><td>Transaksi</td><td>Kendaraan sedang dalam pengiriman</td></tr><tr><td>Repair</td><td>Kendaraan sedang dalam perbaikan</td></tr><tr><td>Idle</td><td>Kendaraan tidak sedang digunakan</td></tr></tbody></table><p>Klik card untuk filter tampilan ke kategori tersebut.</p><h3 id="informasi-per-kendaraan" tabindex="-1">Informasi per Kendaraan <a class="header-anchor" href="#informasi-per-kendaraan" aria-label="Permalink to &quot;Informasi per Kendaraan&quot;">​</a></h3><ul><li>Plat nomor dan jenis kendaraan</li><li>Nama driver yang ditugaskan</li><li>Rute pengiriman (jika sedang transaksi)</li><li>Tanggal delivery dan arrival</li><li>Durasi pengiriman</li></ul><h3 id="pencarian" tabindex="-1">Pencarian <a class="header-anchor" href="#pencarian" aria-label="Permalink to &quot;Pencarian&quot;">​</a></h3><p>Cari berdasarkan plat nomor, jenis kendaraan, atau nama driver.</p><h2 id="lokasi-truk-gps-map" tabindex="-1">Lokasi Truk (GPS Map) <a class="header-anchor" href="#lokasi-truk-gps-map" aria-label="Permalink to &quot;Lokasi Truk (GPS Map)&quot;">​</a></h2><p>Peta live yang menampilkan posisi seluruh armada secara real-time.</p><h3 id="layout-3-panel" tabindex="-1">Layout 3 Panel <a class="header-anchor" href="#layout-3-panel" aria-label="Permalink to &quot;Layout 3 Panel&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Panel</th><th>Fungsi</th></tr></thead><tbody><tr><td>Kiri (Peta)</td><td>Leaflet map dengan marker per truck</td></tr><tr><td>Tengah (Vehicle Detail)</td><td>Detail truck yang dipilih</td></tr><tr><td>Kanan (Fleet List)</td><td>Daftar armada dengan search &amp; filter</td></tr></tbody></table><h3 id="fitur-peta" tabindex="-1">Fitur Peta <a class="header-anchor" href="#fitur-peta" aria-label="Permalink to &quot;Fitur Peta&quot;">​</a></h3><ul><li><strong>Auto-refresh</strong> setiap 30 detik</li><li><strong>Marker clustering</strong> — truck yang berdekatan dikelompokkan</li><li><strong>Klik marker</strong> untuk melihat detail truck</li><li><strong>Refresh Sekarang</strong> — refresh manual</li></ul><h3 id="filter-gps-status" tabindex="-1">Filter GPS Status <a class="header-anchor" href="#filter-gps-status" aria-label="Permalink to &quot;Filter GPS Status&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Warna</th><th>Arti</th></tr></thead><tbody><tr><td>Moving</td><td>Hijau</td><td>Kendaraan bergerak</td></tr><tr><td>Idle</td><td>Kuning</td><td>Kendaraan diam tapi GPS aktif</td></tr><tr><td>Offline</td><td>Abu-abu</td><td>GPS tidak mengirim data</td></tr><tr><td>Belum Terhubung</td><td>—</td><td>Belum ada mapping Wialon</td></tr></tbody></table><h3 id="vehicle-detail-panel-tengah" tabindex="-1">Vehicle Detail (Panel Tengah) <a class="header-anchor" href="#vehicle-detail-panel-tengah" aria-label="Permalink to &quot;Vehicle Detail (Panel Tengah)&quot;">​</a></h3><p>Muncul saat truck dipilih, menampilkan:</p><ul><li>Nama driver</li><li>Wialon Unit ID</li><li>Kecepatan saat ini</li><li>Update GPS terakhir</li><li>Lokasi (alamat hasil reverse geocoding)</li><li>Transaksi aktif (jika ada)</li><li>Repair aktif (jika ada)</li><li>Transaksi terakhir</li></ul><h3 id="fleet-list-panel-kanan" tabindex="-1">Fleet List (Panel Kanan) <a class="header-anchor" href="#fleet-list-panel-kanan" aria-label="Permalink to &quot;Fleet List (Panel Kanan)&quot;">​</a></h3><ul><li>Daftar semua truck dengan status GPS</li><li>Search berdasarkan plat, driver, unit ID, atau rute</li><li>Klik item untuk fokus di peta</li></ul><h2 id="km-bulanan-truk" tabindex="-1">KM Bulanan Truk <a class="header-anchor" href="#km-bulanan-truk" aria-label="Permalink to &quot;KM Bulanan Truk&quot;">​</a></h2><p>Rekap jarak tempuh bulanan per truck berdasarkan data trip Wialon.</p><h3 id="filter-1" tabindex="-1">Filter <a class="header-anchor" href="#filter-1" aria-label="Permalink to &quot;Filter&quot;">​</a></h3><ul><li><strong>Bulan</strong> — pilih periode YYYY-MM</li><li><strong>Pencarian</strong> — cari berdasarkan plat, kendaraan, atau unit Wialon</li></ul><h3 id="summary-cards-1" tabindex="-1">Summary Cards <a class="header-anchor" href="#summary-cards-1" aria-label="Permalink to &quot;Summary Cards&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Card</th><th>Deskripsi</th></tr></thead><tbody><tr><td>Total KM</td><td>Total jarak tempuh semua truck</td></tr><tr><td>Truk Berjalan</td><td>Jumlah truck yang punya trip</td></tr><tr><td>Total Trip</td><td>Total jumlah trip semua truck</td></tr><tr><td>Truk Ditampilkan</td><td>Jumlah truck di tabel</td></tr></tbody></table><h3 id="tabel-mileage" tabindex="-1">Tabel Mileage <a class="header-anchor" href="#tabel-mileage" aria-label="Permalink to &quot;Tabel Mileage&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Kolom</th><th>Deskripsi</th></tr></thead><tbody><tr><td>No Truck</td><td>Plat nomor</td></tr><tr><td>Kendaraan</td><td>Jenis kendaraan</td></tr><tr><td>Total KM</td><td>Jarak tempuh bulan itu</td></tr><tr><td>Trip</td><td>Jumlah trip</td></tr><tr><td>Trip Pertama</td><td>Waktu trip pertama</td></tr><tr><td>Trip Terakhir</td><td>Waktu trip terakhir</td></tr><tr><td>Status</td><td>has_trip / no_trip / unlinked / error</td></tr></tbody></table><h3 id="export-excel" tabindex="-1">Export Excel <a class="header-anchor" href="#export-excel" aria-label="Permalink to &quot;Export Excel&quot;">​</a></h3><p>Klik <strong>Export Excel</strong> untuk download data mileage dalam format <code>.xlsx</code>.</p><h2 id="transaksi-—-sales-cost" tabindex="-1">Transaksi — Sales Cost <a class="header-anchor" href="#transaksi-—-sales-cost" aria-label="Permalink to &quot;Transaksi — Sales Cost&quot;">​</a></h2><p>Halaman utama untuk mengelola transaksi pengiriman.</p><h3 id="filter-pencarian" tabindex="-1">Filter &amp; Pencarian <a class="header-anchor" href="#filter-pencarian" aria-label="Permalink to &quot;Filter &amp; Pencarian&quot;">​</a></h3><ul><li>Filter tanggal (mulai — akhir)</li><li>Pilih kolom pencarian (No SPK, Customer, Driver, dll)</li><li>Kata kunci pencarian</li><li>Filter tahun</li></ul><h3 id="aksi-tersedia" tabindex="-1">Aksi Tersedia <a class="header-anchor" href="#aksi-tersedia" aria-label="Permalink to &quot;Aksi Tersedia&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Aksi</th><th>Fungsi</th></tr></thead><tbody><tr><td>Tambah Transaksi</td><td>Input sales cost baru</td></tr><tr><td>Import Excel</td><td>Import bulk dari file Excel</td></tr><tr><td>Export Excel</td><td>Download data ke Excel</td></tr><tr><td>Cetak Terpilih</td><td>Print SPK untuk transaksi yang dicentang</td></tr></tbody></table><h3 id="kolom-tabel" tabindex="-1">Kolom Tabel <a class="header-anchor" href="#kolom-tabel" aria-label="Permalink to &quot;Kolom Tabel&quot;">​</a></h3><p>No. SPK, Tanggal Kirim, Customer, Sales, Ops Cost, Gross Profit</p><h3 id="detail-transaksi" tabindex="-1">Detail Transaksi <a class="header-anchor" href="#detail-transaksi" aria-label="Permalink to &quot;Detail Transaksi&quot;">​</a></h3><p>Klik baris untuk melihat detail lengkap termasuk:</p><ul><li>Data pengiriman (truck, driver, customer, area)</li><li>Data biaya (price, ops cost, margin)</li><li>Riwayat geofence pengiriman (jika ada route tracking)</li></ul><h2 id="transaksi-—-subcontractor" tabindex="-1">Transaksi — Subcontractor <a class="header-anchor" href="#transaksi-—-subcontractor" aria-label="Permalink to &quot;Transaksi — Subcontractor&quot;">​</a></h2><p>Mengelola transaksi yang dikerjakan oleh subcontractor.</p><h3 id="kolom-tabel-1" tabindex="-1">Kolom Tabel <a class="header-anchor" href="#kolom-tabel-1" aria-label="Permalink to &quot;Kolom Tabel&quot;">​</a></h3><p>Delivery Date, Nama Subcont, Nama Customer, Warehouse, Nomor Surat Jalan, Sales, Gross Profit</p><h3 id="aksi" tabindex="-1">Aksi <a class="header-anchor" href="#aksi" aria-label="Permalink to &quot;Aksi&quot;">​</a></h3><ul><li>Tambah Transaksi</li><li>Export Excel</li><li>Edit / Detail / Hapus (admin only untuk hapus)</li></ul><h2 id="transaksi-—-repair" tabindex="-1">Transaksi — Repair <a class="header-anchor" href="#transaksi-—-repair" aria-label="Permalink to &quot;Transaksi — Repair&quot;">​</a></h2><p>Mengelola data perbaikan kendaraan.</p><h3 id="akses-role" tabindex="-1">Akses Role <a class="header-anchor" href="#akses-role" aria-label="Permalink to &quot;Akses Role&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Role</th><th>Akses</th></tr></thead><tbody><tr><td>Admin</td><td>Full CRUD</td></tr><tr><td>User</td><td>View + Create (tidak bisa edit)</td></tr><tr><td>Mekanik</td><td>Full CRUD</td></tr></tbody></table><h2 id="data-transport" tabindex="-1">Data Transport <a class="header-anchor" href="#data-transport" aria-label="Permalink to &quot;Data Transport&quot;">​</a></h2><p>Halaman untuk mengelola data historis kendaraan dan supir.</p><h3 id="data-truck" tabindex="-1">Data Truck <a class="header-anchor" href="#data-truck" aria-label="Permalink to &quot;Data Truck&quot;">​</a></h3><p>Data administratif kendaraan: dokumen, masa berlaku, foto.</p><h3 id="data-chasis" tabindex="-1">Data Chasis <a class="header-anchor" href="#data-chasis" aria-label="Permalink to &quot;Data Chasis&quot;">​</a></h3><p>Data chasis/trailer: dokumen, spesifikasi.</p><h3 id="data-supir" tabindex="-1">Data Supir <a class="header-anchor" href="#data-supir" aria-label="Permalink to &quot;Data Supir&quot;">​</a></h3><p>Data administratif supir: dokumen SIM, KTP, foto, masa berlaku.</p><h3 id="fitur-umum" tabindex="-1">Fitur Umum <a class="header-anchor" href="#fitur-umum" aria-label="Permalink to &quot;Fitur Umum&quot;">​</a></h3><ul><li>Filter tanggal dan pencarian</li><li>Import/Export Excel</li><li>CRUD (Create, Read, Update, Delete)</li><li>Upload dokumen pendukung</li></ul><h2 id="user-profile" tabindex="-1">User Profile <a class="header-anchor" href="#user-profile" aria-label="Permalink to &quot;User Profile&quot;">​</a></h2><ul><li>Lihat informasi akun</li><li>Update password</li><li>Update foto profil</li></ul><h2 id="tips-penggunaan" tabindex="-1">Tips Penggunaan <a class="header-anchor" href="#tips-penggunaan" aria-label="Permalink to &quot;Tips Penggunaan&quot;">​</a></h2><ol><li><strong>Gunakan filter</strong> untuk mempersempit data yang ditampilkan</li><li><strong>Export Excel</strong> untuk analisis data lebih lanjut</li><li><strong>Bookmark halaman</strong> yang sering diakses</li><li><strong>Hard refresh</strong> (<code>Ctrl+Shift+R</code>) jika tampilan tidak update</li><li><strong>Cek Monitoring Kendaraan</strong> untuk overview cepat status armada</li></ol>',101)])])}const p=t(n,[["render",l]]);export{m as __pageData,p as default};
